CREATE TABLE "agents" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "secretEncrypted" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'active', "revision" INTEGER NOT NULL DEFAULT 1, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "agents_pkey" PRIMARY KEY ("id"));
CREATE TABLE "delegations" ("agentId" TEXT NOT NULL, "totalLimitPaise" INTEGER NOT NULL, "perTransactionLimitPaise" INTEGER NOT NULL, "transactionCountLimit" INTEGER NOT NULL, "frequencyCount" INTEGER NOT NULL, "frequencyUnit" TEXT NOT NULL, "allowedCategoriesJson" TEXT NOT NULL, "allowedMerchantsJson" TEXT NOT NULL, "currency" TEXT NOT NULL DEFAULT 'INR', "expiresAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "delegations_pkey" PRIMARY KEY ("agentId"));
CREATE TABLE "budgets_usage" ("agentId" TEXT NOT NULL, "spentPaise" INTEGER NOT NULL DEFAULT 0, "reservedPaise" INTEGER NOT NULL DEFAULT 0, "transactionCount" INTEGER NOT NULL DEFAULT 0, CONSTRAINT "budgets_usage_pkey" PRIMARY KEY ("agentId"));
CREATE TABLE "decisions" ("id" TEXT NOT NULL, "requestId" TEXT NOT NULL, "agentId" TEXT NOT NULL, "agentName" TEXT NOT NULL, "merchant" TEXT NOT NULL, "amountPaise" INTEGER NOT NULL, "currency" TEXT NOT NULL, "verdict" TEXT NOT NULL, "reasonCode" TEXT NOT NULL, "reasonText" TEXT NOT NULL, "proposalJson" TEXT NOT NULL, "checksJson" TEXT NOT NULL, "riskJson" TEXT, "evidenceJson" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "decisions_pkey" PRIMARY KEY ("id"));
CREATE TABLE "approvals" ("id" TEXT NOT NULL, "decisionId" TEXT NOT NULL, "agentId" TEXT NOT NULL, "amountPaise" INTEGER NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "approvals_pkey" PRIMARY KEY ("id"));
CREATE TABLE "denials" ("id" TEXT NOT NULL, "decisionId" TEXT NOT NULL, "agentId" TEXT NOT NULL, "reasonCode" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "denials_pkey" PRIMARY KEY ("id"));
CREATE TABLE "nonces" ("requestId" TEXT NOT NULL, "agentId" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "nonces_pkey" PRIMARY KEY ("requestId"));
CREATE TABLE "authorization_artifacts" ("approvalId" TEXT NOT NULL, "decisionId" TEXT NOT NULL, "agentId" TEXT NOT NULL, "nonce" TEXT NOT NULL, "payloadJson" TEXT NOT NULL, "amountPaise" INTEGER NOT NULL, "expiresAt" TIMESTAMP(3) NOT NULL, "status" TEXT NOT NULL DEFAULT 'issued', "consumedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "authorization_artifacts_pkey" PRIMARY KEY ("approvalId"));
CREATE TABLE "transactions" ("id" TEXT NOT NULL, "approvalId" TEXT NOT NULL, "agentId" TEXT NOT NULL, "amountPaise" INTEGER NOT NULL, "currency" TEXT NOT NULL, "merchant" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'pending', "provider" TEXT NOT NULL, "providerOrderId" TEXT, "providerPaymentId" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "transactions_pkey" PRIMARY KEY ("id"));
CREATE TABLE "webhook_receipts" ("eventId" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "webhook_receipts_pkey" PRIMARY KEY ("eventId"));
CREATE TABLE "audit_events" ("id" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "actor" TEXT NOT NULL, "agentId" TEXT, "eventType" TEXT NOT NULL, "verdict" TEXT, "contextJson" TEXT NOT NULL, CONSTRAINT "audit_events_pkey" PRIMARY KEY ("id"));
CREATE INDEX "decisions_agentId_createdAt_idx" ON "decisions"("agentId", "createdAt"); CREATE UNIQUE INDEX "approvals_decisionId_key" ON "approvals"("decisionId"); CREATE INDEX "approvals_agentId_createdAt_idx" ON "approvals"("agentId", "createdAt"); CREATE UNIQUE INDEX "denials_decisionId_key" ON "denials"("decisionId"); CREATE UNIQUE INDEX "authorization_artifacts_decisionId_key" ON "authorization_artifacts"("decisionId"); CREATE UNIQUE INDEX "authorization_artifacts_nonce_key" ON "authorization_artifacts"("nonce"); CREATE INDEX "authorization_artifacts_agentId_status_idx" ON "authorization_artifacts"("agentId", "status"); CREATE UNIQUE INDEX "transactions_approvalId_key" ON "transactions"("approvalId"); CREATE UNIQUE INDEX "transactions_providerOrderId_key" ON "transactions"("providerOrderId"); CREATE INDEX "audit_events_agentId_createdAt_idx" ON "audit_events"("agentId", "createdAt");
CREATE OR REPLACE FUNCTION prevent_audit_mutation() RETURNS trigger AS $$ BEGIN RAISE EXCEPTION 'audit_events is append-only'; END; $$ LANGUAGE plpgsql;
CREATE TRIGGER "audit_events_no_update" BEFORE UPDATE ON "audit_events" FOR EACH ROW EXECUTE FUNCTION prevent_audit_mutation(); CREATE TRIGGER "audit_events_no_delete" BEFORE DELETE ON "audit_events" FOR EACH ROW EXECUTE FUNCTION prevent_audit_mutation();
